mapper.select:
SELECT id, book_id, member_id, loan_date, due_date, return_date, status, version
FROM loan
WHERE id = #{id}

SELECT id, book_id, member_id, loan_date, due_date, return_date, status, version FROM loan WHERE member_id = #{memberId}
AND status = 'ACTIVE'
ORDER BY loan_date DESC

mapper.insert:
INSERT INTO loan (book_id, member_id, loan_date, due_date, return_date, status)
SELECT #{bookId}, #{memberId}, #{loanDate}, #{dueDate}, #{returnDate}, #{status}
FROM DUAL
WHERE NOT EXISTS (
    SELECT 1 FROM loan WHERE book_id = #{bookId} AND member_id = #{memberId} AND status = 'ACTIVE'
)
